with session_stats as (select session_id, count(case when page = '/cart' then 1 end) as cart_count, round(avg(duration_sec), 2) as avg_duration_sec from web_events where session_id = 15 group by session_id) select s.id, s.device, s.customer_id, ss.cart_count, ss.avg_duration_sec from sessions s inner join session_stats ss on s.id = ss.session_id order by device, avg_duration_sec desc;
